style.css:
@-moz-document domain("google.com") {
/* Скрыть стандартный логотип Google */
    .lnXdpd {
        display: none;
    }

    /* Заменить логотип Google на кастомное изображение */
    #hplogo {
        background: url('https://i.imgur.com/8AvzVQw.mp4') no-repeat center;
        background-size: contain; /* Настроить изображение под размер логотипа */
        width: 272px; /* Размер логотипа */
        height: 92px; /* Размер логотипа */
    }
}
